#include "game.hpp"
#include <algorithm>
#include <cctype>
#include <iostream>
namespace echodrive {
Game::Game():settings_(loadSettings("echodrive.cfg")),voice_(settings_.language),streets_{{1,"شارع القاهرة","Cairo Street","شارع حضري مزدحم"},{2,"طريق نيويورك","New York Avenue","طريق سريع متعدد المسارات"},{3,"طريق طوكيو","Tokyo Road","شارع هادئ بمنعطفات"}}{}
void Game::menu()const{std::cout<<"\n=== EchoDrive | Ahmed Samy Studio ===\n1 تقدم | 2 فرامل | 3 يمين | 4 يسار | 5 أسرع | 6 أبطئ\na قيادة آلية | m قيادة يدوية | r إعادة | s الحالة | q خروج\n> ";}
void Game::selectStreet(){std::cout<<"اختر الشارع 1 القاهرة، 2 نيويورك، 3 طوكيو: ";int n=1;std::cin>>n;std::cin.ignore(10000,'\n');if(n<1||n>3)n=1;settings_.street=n;auto&x=streets_[n-1];voice_.announce("بدأت "+x.ar+". "+x.description,"Starting "+x.en+". "+x.description);}
Command Game::parse(const std::string&r)const{if(r=="1"||r=="w"||r=="تقدم")return Command::Forward;if(r=="2"||r=="توقف"||r=="فرامل")return Command::Brake;if(r=="3"||r=="right"||r=="يمين")return Command::Right;if(r=="4"||r=="left"||r=="يسار")return Command::Left;if(r=="5"||r=="أسرع")return Command::Faster;if(r=="6"||r=="أبطئ")return Command::Slower;if(r=="a"||r=="قيادة آلية")return Command::Auto;if(r=="m"||r=="قيادة يدوية")return Command::Manual;if(r=="r"||r=="إعادة")return Command::Reset;if(r=="s")return Command::Repeat;if(r=="q"||r=="خروج")return Command::Quit;return Command::Unknown;}
void Game::status()const{std::string d=heading_<0?"يسار":heading_>0?"يمين":"مستقيم";std::string e=heading_<0?"left":heading_>0?"right":"straight";voice_.announce("السرعة "+std::to_string((int)speed_)+" كيلومتر، الاتجاه "+d,"Speed "+std::to_string((int)speed_)+" kilometers per hour, direction "+e);}
void Game::handle(Command c){switch(c){case Command::Forward:speed_=std::min(120.0,speed_+8);voice_.announce("تقدم","Moving forward");break;case Command::Brake:speed_=std::max(0.0,speed_-20);voice_.announce("فرامل","Braking");break;case Command::Right:heading_=1;voice_.announce("يمين","Turning right");break;case Command::Left:heading_=-1;voice_.announce("يسار","Turning left");break;case Command::Faster:speed_=std::min(120.0,speed_+15);status();break;case Command::Slower:speed_=std::max(0.0,speed_-15);status();break;case Command::Auto:settings_.automaticDriving=true;voice_.announce("تم تشغيل القيادة الآلية","Automatic driving enabled");break;case Command::Manual:settings_.automaticDriving=false;voice_.announce("تم تشغيل القيادة اليدوية","Manual driving enabled");break;case Command::Reset:speed_=0;heading_=0;voice_.announce("أعيدت الرحلة","Trip reset");break;case Command::Repeat:status();break;case Command::Quit:saveSettings(settings_,"echodrive.cfg");voice_.announce("إلى اللقاء","Goodbye");break;case Command::Unknown:voice_.announce("لم أفهم الأمر","Command not understood");}}
void Game::run(){voice_.announce("مرحبًا بك في EchoDrive. قد بدون الاعتماد على النظر.","Welcome to EchoDrive. Drive beyond sight.");selectStreet();for(;;){menu();std::string x;if(!std::getline(std::cin,x))break;Command c=parse(x);handle(c);if(c==Command::Quit)break;}}
}
